module.exports = {
    onConnect: function(transport, config) {
        engine.setStatus('connecting', 'Connecting...');
    },
    onTransportReady: function(transport, config) {
        engine.setStatus('connected', 'Ready');
        // Query initial state
        transport.send('STATUS?\r\n');
    },
    onAction: function(transport, actionId, params) {
        if (actionId === 'set_power') {
            var cmd = params.state === 'on' ? 'POWER ON\r\n' : 'POWER OFF\r\n';
            transport.send(cmd);
            return 'Sent ' + params.state;
        } else if (actionId === 'select_input') {
            transport.send('INPUT ' + params.channel + '\r\n');
            return 'Switched to input ' + params.channel;
        }
        return 'Unknown action';
    },
    onMessage: function(transport, text, bytes) {
        text = text.trim();
        if (text.startsWith('POWER=')) {
            var val = text.substring(6).toLowerCase();
            engine.setVariable('power_state', val);
        } else if (text.startsWith('INPUT=')) {
            var inp = text.substring(6);
            engine.setVariable('active_input', inp);
        }
    },
    onHeartbeat: function(transport) {
        transport.send('PING\r\n');
    },
    onDisconnect: function() {
        engine.setStatus('disconnected', 'Disconnected');
    }
};
